cat > /tmp/lamp-scratch/standin.mjs <<'EOF'
// Scratch only: the designer's intended P0 west bedroom layout (room-6.mjs comment) on a copy of build.nbt,
// plus a named set of lanterns given on argv. Writes /tmp/lamp-scratch/<name>.nbt. Never touches the real build.
import { load, bed } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";
const [src, name, ...spots] = process.argv.slice(2);
const g = load(src);
const set = (x, y, z, block, state = {}) => g.set(x, y, z, `minecraft:${block}`, state);
// feet layer y6
for (const x of [3, 4]) { set(x, 6, 14, "barrel", { facing: "up", open: "false" }); set(x, 6, 19, "barrel", { facing: "up", open: "false" }); set(x, 6, 20, "barrel", { facing: "up", open: "false" }); }
set(3, 6, 15, "oak_fence");
bed(g, [4, 6, 17], "west", "red");
bed(g, [4, 6, 18], "west", "blue");
// head layer y7: potted poppy on the north dresser
set(4, 7, 14, "potted_poppy");
// lanterns: each "x,y,z" spot, standing (hanging false)
for (const s of spots) {
  const [x, y, z] = s.split(",").map(Number);
  set(x, y, z, "lantern", { hanging: "false", waterlogged: "false" });
}
g.save(`/tmp/lamp-scratch/${name}.nbt`);
console.log(name, "saved with lanterns", spots.join(" ") || "(none)");
EOF
